import{_ as s,o as a,c as t,a6 as r}from"./chunks/framework.BrkgobfX.js";const T=JSON.parse('{"title":"HTTP/3 总览","description":"TCP 队头阻塞为什么无法在 TCP 上解决，以及 h3 = HTTP/2 语义 + QUIC 传输。","frontmatter":{"title":"HTTP/3 总览","description":"TCP 队头阻塞为什么无法在 TCP 上解决，以及 h3 = HTTP/2 语义 + QUIC 传输。","source":"https://daiw.org/manual/http2-3/h3-overview"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h3-overview.md","filePath":"manual/computer-programming/http2-3/h3-overview.md"}'),e={name:"manual/computer-programming/http2-3/h3-overview.md"};function p(l,n,i,o,d,c){return a(),t("div",null,[...n[0]||(n[0]=[r(`<h1 id="http-3-总览" tabindex="-1">HTTP/3 总览 <a class="header-anchor" href="#http-3-总览" aria-label="Permalink to &quot;HTTP/3 总览&quot;">​</a></h1><p>TCP 队头阻塞为什么无法在 TCP 上解决，以及 h3 = HTTP/2 语义 + QUIC 传输。</p><h2 id="唯一的动机" tabindex="-1">唯一的动机 <a class="header-anchor" href="#唯一的动机" aria-label="Permalink to &quot;唯一的动机&quot;">​</a></h2><p>HTTP/2 消除了 HTTP 层的队头阻塞，但<strong>所有流仍共享一条 TCP 连接</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 是一条有序字节流。内核的契约是:</span></span>
<span class="line"><span>「按发送顺序、无缺口地把字节交给应用」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  发送: [流1-A][流3-B][流1-C][流5-D]</span></span>
<span class="line"><span>                ↑ 丢失</span></span>
<span class="line"><span>  接收: 流1-A 已交付</span></span>
<span class="line"><span>        流3-B 丢了 → 内核必须等重传</span></span>
<span class="line"><span>        流1-C、流5-D 已完整到达，但被扣在内核缓冲区</span></span>
<span class="line"><span>        → 三个流一起卡住，等一个与它们无关的包</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>根源在于 TCP 不知道流的存在</strong>。它只看到一条字节流，缺口就是缺口。这一点<strong>无法在 TCP 之上修复</strong>——无论 HTTP 层怎么设计，都改变不了内核的交付语义。</p><p>要解决，只能换传输层：让传输层<strong>自己知道有多个独立的流</strong>，某个流丢包时不影响其他流的交付。这就是 QUIC，也是 HTTP/3 存在的全部理由。</p><h2 id="为什么不改-tcp" tabindex="-1">为什么不改 TCP <a class="header-anchor" href="#为什么不改-tcp" aria-label="Permalink to &quot;为什么不改 TCP&quot;">​</a></h2><p>理论上可以给 TCP 加多流支持（SCTP 就是这么做的），实际不可行：</p><table tabindex="0"><thead><tr><th>障碍</th><th>说明</th></tr></thead><tbody><tr><td><strong>中间件僵化（ossification）</strong></td><td>全球的 NAT、防火墙、负载均衡器只认识 TCP/UDP。新传输协议号的包会被大量丢弃</td></tr><tr><td><strong>内核部署周期</strong></td><td>TCP 实现在操作系统内核里，一个改动要等数年才能覆盖大多数设备</td></tr><tr><td><strong>TCP 头部明文</strong></td><td>中间件会窥探甚至改写 TCP 选项，导致新特性被破坏</td></tr></tbody></table><p>QUIC 的对策：</p><ul><li><strong>跑在 UDP 上</strong> —— UDP 到处都通，无需中间件升级。</li><li><strong>实现在用户态</strong> —— 随浏览器/服务端软件更新，迭代周期从年降到周。</li><li><strong>几乎全部加密</strong> —— 连包序号和大部分头部都加密，中间件<strong>看不到也改不了</strong>，从根上防止再次僵化。</li></ul><h2 id="http-3-http-2-语义-quic" tabindex="-1">HTTP/3 = HTTP/2 语义 + QUIC <a class="header-anchor" href="#http-3-http-2-语义-quic" aria-label="Permalink to &quot;HTTP/3 = HTTP/2 语义 + QUIC&quot;">​</a></h2><p>分层对比：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1        HTTP/2          HTTP/3</span></span>
<span class="line"><span>─────────────────────────────────────────</span></span>
<span class="line"><span>HTTP 语义       HTTP 语义        HTTP 语义      ← 三版完全相同 (RFC 9110)</span></span>
<span class="line"><span>─────────────────────────────────────────</span></span>
<span class="line"><span>文本报文        二进制帧         二进制帧        ← h3 帧格式与 h2 相似但不同</span></span>
<span class="line"><span>                HPACK           QPACK          ← 为乱序交付重新设计</span></span>
<span class="line"><span>                流/多路复用      ↓ 下沉到 QUIC</span></span>
<span class="line"><span>                流量控制         ↓ 下沉到 QUIC</span></span>
<span class="line"><span>─────────────────────────────────────────</span></span>
<span class="line"><span>TLS (可选)      TLS (事实必需)   ↓ 内建于 QUIC</span></span>
<span class="line"><span>─────────────────────────────────────────</span></span>
<span class="line"><span>TCP             TCP             QUIC</span></span>
<span class="line"><span>                                UDP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p><strong>HTTP/3 把 h2 的三样东西下沉到了传输层</strong>：流的多路复用、流量控制、连接管理（部分）。h3 自己只剩下「帧格式 + 字段压缩 + HTTP 语义映射」。</p><p>结果是 h3 规范（RFC 9114）比 h2 规范<strong>短得多</strong>——重活都交给了 QUIC。</p><h2 id="相对-h2-的改进清单" tabindex="-1">相对 h2 的改进清单 <a class="header-anchor" href="#相对-h2-的改进清单" aria-label="Permalink to &quot;相对 h2 的改进清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>改进</th><th>说明</th></tr></thead><tbody><tr><td><strong>消除传输层队头阻塞</strong></td><td>一个流丢包只阻塞该流，其他流照常交付</td></tr><tr><td><strong>握手更快</strong></td><td>TCP+TLS1.3 需 2–3 RTT；QUIC <strong>1 RTT</strong>，会话恢复 <strong>0 RTT</strong></td></tr><tr><td><strong>连接迁移</strong></td><td>用 Connection ID 而非四元组标识连接，<strong>换 IP/网络不断连</strong>（WiFi 切 4G 无感）</td></tr><tr><td><strong>更好的丢包恢复</strong></td><td>单调递增包号消除 TCP 的重传歧义；用户态可用更先进的拥塞控制</td></tr><tr><td><strong>强制加密</strong></td><td>传输层元数据也加密，抗窥探与抗僵化</td></tr><tr><td><strong>无 CONTINUATION 阻塞</strong></td><td>帧结构简化，字段块无需连续独占连接</td></tr></tbody></table><h2 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to &quot;代价&quot;">​</a></h2><p>诚实地列出来：</p><ol><li><strong>CPU 开销更高</strong>。UDP 的内核路径优化远不如 TCP（无 GSO/GRO 硬件卸载的历史积累），加解密也在用户态。实测 h3 的 CPU 消耗常为 h2 的 <strong>2–3 倍</strong>，虽在快速改善。</li><li><strong>UDP 可能被封禁或限速</strong>。部分企业网络与运营商对 UDP 有限制，客户端<strong>必须</strong>保留回落到 h2/1.1 的能力。</li><li><strong>实现成熟度</strong>。QUIC 栈自己实现了拥塞控制、丢包恢复、加密——这些在 TCP 里是内核数十年打磨的成果。</li><li><strong>可观测性下降</strong>。传输层加密后，运维再也不能靠抓包分析 RTT、重传、窗口——排障需依赖端点自己导出的 qlog。</li></ol><h2 id="版本标识与发现" tabindex="-1">版本标识与发现 <a class="header-anchor" href="#版本标识与发现" aria-label="Permalink to &quot;版本标识与发现&quot;">​</a></h2><ul><li>ALPN 标识：<strong><code>h3</code></strong>。</li><li>因为客户端无法预知服务端是否支持 UDP/QUIC，h3 <strong>必须先被发现</strong>——通过 <a href="/Front2Full/manual/computer-programming/http2-3/h3-connection"><code>Alt-Svc</code> 字段或 DNS HTTPS 记录</a>。</li><li>首次访问几乎总是走 h2/1.1，随后才升级到 h3。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">QUIC 传输层</a>。</p>`,25)])])}const g=s(e,[["render",p]]);export{T as __pageData,g as default};
